  async function runMessage(text:string,requestId:string){
    if(busy)return;setBusy(true);setError('');setRetry(null);setInput('');
    const controller=new AbortController();streamController.current=controller;const tempId=`stream-${requestId}`;
    try{await streamMessage(text,requestId,controller.signal,{
      onMeta:data=>{setMessages(current=>current.some(item=>item.id===data.user.id)?current:[...current,data.user]);scrollChatToLatest();},
      onDelta:delta=>{setMessages(current=>{const found=current.find(item=>item.id===tempId);return found?current.map(item=>item.id===tempId?{...item,text:item.text+delta}:item):[...current,{id:tempId,speaker:'assistant',kind:'text',text:delta,createdAt:new Date().toISOString()}];});scrollChatToLatest();},
      onDone:data=>{const marked=/^\s*(?:\[voice\]|\[\[voice\]\]|【voice】)/i.test(data.assistant.text);const clean=data.assistant.text.replace(/^\s*(?:\[voice\]|\[\[voice\]\]|【voice】)\s*/i,'');const assistant={...data.assistant,text:clean,...(marked?{voiceStatus:'generating' as const}: {})};setMessages(current=>current.map(item=>item.id===tempId?assistant:item));scrollChatToLatest();if(marked)synthesizeVoice(data.assistant.id).then(audio=>setMessages(current=>current.map(item=>item.id===data.assistant.id?{...item,kind:'voice',text:audio.transcript,audioUrl:audio.audioUrl,durationMs:audio.duration_ms,voiceStatus:'ready'}:item))).catch(reason=>{setMessages(current=>current.map(item=>item.id===data.assistant.id?{...item,voiceStatus:'failed'}:item));setError(reason instanceof Error?reason.message:'语音生成失败');});},
    });}
    catch(reason){setMessages(current=>current.filter(item=>item.id!==tempId));setRetry({text,id:requestId});setError(reason instanceof DOMException&&reason.name==='AbortError'?'已停止回复，可以继续重试。':reason instanceof Error?reason.message:'发送失败');}
    finally{streamController.current=null;setBusy(false);}
  }
  async function submit(event:FormEvent){event.preventDefault();const text=input.trim();if(!text||busy)return;await runMessage(text,crypto.randomUUID());}
  async function loadOlderMessages(){if(loadingOlderMessages||!hasOlderMessages)return;setLoadingOlderMessages(true);const container=messagesRef.current,beforeHeight=container?.scrollHeight||0,beforeTop=container?.scrollTop||0;try{const older=await loadMessages(100,messages.filter(item=>!item.id.startsWith('stream-')).length);setMessages(current=>mergeMessages(current,older));setHasOlderMessages(older.length===100);window.requestAnimationFrame(()=>{if(messagesRef.current)messagesRef.current.scrollTop=beforeTop+(messagesRef.current.scrollHeight-beforeHeight);});}catch(reason){setError(reason instanceof Error?reason.message:'读取更早聊天失败');}finally{setLoadingOlderMessages(false);}}
  async function importHistory(event:ChangeEvent<HTMLInputElement>){const file=event.target.files?.[0];if(!file||importing)return;setImporting(true);setError('');try{setImportBatch(await uploadChatHistory(file));}catch(reason){setError(reason instanceof Error?reason.message:'读取聊天文件失败');}finally{setImporting(false);event.target.value='';}}
  async function screenCandidates(){if(!importBatch||importing)return;setImporting(true);setError('');try{await createLocalCandidates(importBatch.id);const result=await loadCandidates(importBatch.id);setCandidates(result.items);setCandidateTotal(result.total);setCandidateOffset(0);setSelected([]);}catch(reason){setError(reason instanceof Error?reason.message:'本地初筛失败');}finally{setImporting(false);}}
  async function changeCandidatePage(offset:number){if(!importBatch||importing)return;setImporting(true);try{const result=await loadCandidates(importBatch.id,offset);setCandidates(result.items);setCandidateTotal(result.total);setCandidateOffset(offset);setSelected([]);}finally{setImporting(false);}}
  async function confirmCandidates(){if(!importBatch||!selected.length||importing)return;setImporting(true);setError('');try{const outcome=await acceptCandidates(importBatch.id,selected);const result=await loadCandidates(importBatch.id,candidateOffset);setCandidates(result.items);setCandidateTotal(result.total);setSelected(outcome.blockedConflicts);if(outcome.blockedConflicts.length)setError(`${outcome.blockedConflicts.length} 条候选存在矛盾，请先编辑或忽略，系统没有强行覆盖原记忆。`);}catch(reason){setError(reason instanceof Error?reason.message:'写入长期记忆失败');}finally{setImporting(false);}}
  async function inspectCandidates(){if(!importBatch||importing)return;setImporting(true);setError('');try{const result=await analyzeCandidates(importBatch.id);const page=await loadCandidates(importBatch.id,candidateOffset);setCandidates(page.items);setError(`检查完成：${result.counts.conflict||0} 组冲突，${(result.counts.similar||0)+(result.counts.existing||0)} 组相似内容。`);}catch(reason){setError(reason instanceof Error?reason.message:'检查失败');}finally{setImporting(false);}}
  async function saveCandidate(){if(!importBatch||!editingId||importing)return;setImporting(true);setError('');try{const updated=await updateCandidate(importBatch.id,editingId,editLayer,editSummary);setCandidates(items=>items.map(item=>item.id===editingId?updated:item));setEditingId('');}catch(reason){setError(reason instanceof Error?reason.message:'候选修改失败');}finally{setImporting(false);}}
  async function ignoreCandidates(){if(!importBatch||!selected.length||importing)return;setImporting(true);try{await rejectCandidates(importBatch.id,selected);const result=await loadCandidates(importBatch.id,candidateOffset);setCandidates(result.items);setCandidateTotal(result.total);setSelected([]);}finally{setImporting(false);}}
  async function showReport(){if(!importBatch||importing)return;setImporting(true);try{setReport(await loadIntegrityReport(importBatch.id));}catch(reason){setError(reason instanceof Error?reason.message:'生成报告失败');}finally{setImporting(false);}}
  async function makeBackup(){if(importing)return;setImporting(true);setBackupStatus('');try{await downloadBackup();setBackupStatus('备份已经生成并下载，请妥善保存。');}catch(reason){setBackupStatus(reason instanceof Error?reason.message:'备份失败');}finally{setImporting(false);}}
  async function inspectBackup(event:ChangeEvent<HTMLInputElement>){const file=event.target.files?.[0];if(!file||importing)return;setImporting(true);setBackupStatus('');try{setRestore(await previewRestore(file));}catch(reason){setBackupStatus(reason instanceof Error?reason.message:'备份检查失败');}finally{setImporting(false);event.target.value='';}}
  async function mergeBackup(){if(!restore||importing)return;setImporting(true);try{const result=await confirmRestore(restore.token);setBackupStatus(`安全合并完成，共补充 ${Object.values(result.inserted).reduce((sum,count)=>sum+count,0)} 条缺失数据。`);setRestore(null);}catch(reason){setBackupStatus(reason instanceof Error?reason.message:'恢复失败');}finally{setImporting(false);}}
  async function prepareExtraction(){if(!importBatch||importing)return;setImporting(true);setError('');let job:ExtractionJob|null=null;try{job=await createExtractionJob(importBatch.id);setExtractionJob(job);}catch(reason){setError(reason instanceof Error?reason.message:'创建任务失败');}finally{setImporting(false);}if(job)await extractAll(job);}
  async function extractAll(seed=extractionJob){if(!importBatch||!seed||importing)return;setImporting(true);setError('');extractionStopRef.current=false;let current=seed;try{while(!extractionStopRef.current&&['ready','running'].includes(current.status)){const result=await runExtractionStep(importBatch.id,current.id);current=result.job;setExtractionJob(current);const page=await loadCandidates(importBatch.id,candidateOffset);setCandidates(page.items);setCandidateTotal(page.total);if(!['ready','running'].includes(current.status))break;}if(extractionStopRef.current&&['ready','running'].includes(current.status)){current=await controlExtractionJob(importBatch.id,current.id,'pause');setExtractionJob(current);}}catch(reason){setError(reason instanceof Error?reason.message:'精提取失败，可以从当前进度继续。');}finally{setImporting(false);}}
  async function continueExtraction(action:'resume'|'retry'){if(!importBatch||!extractionJob||importing)return;setImporting(true);try{const ready=await controlExtractionJob(importBatch.id,extractionJob.id,action);setExtractionJob(ready);setImporting(false);await extractAll(ready);}catch(reason){setError(reason instanceof Error?reason.message:'无法继续提取');setImporting(false);}}
  async function saveMemory(){if(!memoryDraft||importing)return;setImporting(true);try{const updated=await updateMemory(memoryDraft);setMemories(items=>items.map(item=>item.id===updated.id?updated:item));setMemoryDraft(null);}catch(reason){setError(reason instanceof Error?reason.message:'记忆修改失败');}finally{setImporting(false);}}
  async function archiveMemory(id:string){if(importing)return;setImporting(true);try{const updated=await setMemoryStatus(id,'archived');setMemories(items=>items.map(item=>item.id===id?updated:item));}finally{setImporting(false);}}
  async function strengthenMemory(id:string){if(importing)return;setImporting(true);try{const updated=await reinforceMemory(id);setMemories(items=>items.map(item=>item.id===id?updated:item));}finally{setImporting(false);}}
  async function organizeRecentChat(){if(importing)return;setImporting(true);setRecentMemoryStatus('正在整理最近聊天…');try{const result=await extractRecentChatMemories();setRecentMemoryStatus(result.created?`已生成 ${result.created} 条待确认记忆`:result.reason||'最近聊天没有需要长期保存的内容');setMemories(await loadMemories());}catch(reason){setRecentMemoryStatus(reason instanceof Error?reason.message:'最近聊天整理失败');}finally{setImporting(false);}}
  async function showMemoryEvidence(id:string){if(evidenceOpen===id){setEvidenceOpen('');return;}setEvidenceOpen(id);if(memoryEvidence[id])return;try{const evidence=await loadMemoryEvidence(id);setMemoryEvidence(current=>({...current,[id]:evidence}));}catch(reason){setError(reason instanceof Error?reason.message:'读取原文证据失败');}}
  async function removeMemory(id:string){if(importing||!window.confirm('永久删除后，这条记忆及其原文证据不会出现在后续备份中。确认删除吗？'))return;setImporting(true);try{await deleteMemory(id);setMemories(items=>items.filter(item=>item.id!==id));setEvidenceOpen('');}catch(reason){setError(reason instanceof Error?reason.message:'永久删除失败');}finally{setImporting(false);}}
  async function beginCall(){if(activeCall||busy)return;setBusy(true);setError('');try{const call=await startCall('outgoing');setActiveCall(call);setCallSeconds(0);const opening=await openOutgoingCall(call.id);setActiveCall(current=>current?{...current,turns:[...current.turns,{speaker:'assistant',text:opening.assistant.text,createdAt:new Date().toISOString(),messageId:opening.assistant.messageId}]}:current);setBusy(false);await playCallVoice(opening.assistant.messageId,opening.assistant.text);}catch(reason){setError(reason instanceof Error?reason.message:'通话建立失败');resumeListeningRef.current=true;setBusy(false);}}
  async function organizeCallMemories(callId:string){setCallMemoryStatus('正在整理这次通话…');setLastEndedCallId(callId);try{const result=await extractCallMemories(callId);setCallMemoryStatus(result.created?`已生成 ${result.created} 条待确认记忆`:'这次通话没有需要长期保存的内容');if(result.created&&page==='memories')setMemories(await loadMemories());}catch{setCallMemoryStatus('通话已保存，记忆整理暂时失败');}}
  async function hangUp(){if(!activeCall)return;callReplyController.current?.abort();callReplyController.current=null;recognitionRef.current?.stop();callAudioRef.current?.pause();callAudioRef.current=null;resumeListeningRef.current=false;setCallListening(false);setCallSpeaking(false);setBusy(true);try{const ended=await endCall(activeCall.id);setCalls(items=>[ended,...items.filter(item=>item.id!==ended.id)]);setActiveCall(null);setCallSeconds(0);setCallCaption('');setMessages(await loadMessages());void organizeCallMemories(ended.id);}finally{setBusy(false);}}
  async function acceptIncoming(){if(!incomingCall||busy)return;setBusy(true);try{const call=await answerCall(incomingCall.id);setActiveCall(call);setIncomingCall(null);setCallSeconds(0);nav('calls');setBusy(false);const opener=call.turns.at(-1);if(opener?.speaker==='assistant'&&opener.messageId)await playCallVoice(opener.messageId,opener.text);}catch(reason){setError(reason instanceof Error?reason.message:'接听失败');setBusy(false);}}
  async function declineIncoming(){if(!incomingCall||busy)return;setBusy(true);try{const call=await endCall(incomingCall.id,'declined');setCalls(items=>[call,...items.filter(item=>item.id!==call.id)]);setIncomingCall(null);}finally{setBusy(false);}}
  async function changeCompanion(patch:Partial<CompanionSettings>){if(!companionSettings||busy)return;const next={...companionSettings,...patch};setCompanionSettings(next);setBusy(true);try{setCompanionSettings(await saveCompanionSettings(next));}catch(reason){setError(reason instanceof Error?reason.message:'保存失败');setCompanionSettings(companionSettings);}finally{setBusy(false);}}
  async function enableNotifications(){setBusy(true);setPushStatus('');try{await subscribeToPush();setPushStatus('通知已经开启。安装到主屏幕后，网页不在前台时也能收到推送。');}catch(reason){setPushStatus(reason instanceof Error?reason.message:'开启通知失败');}finally{setBusy(false);}}
  async function retryNotifications(){if(busy)return;setBusy(true);try{const result=await retryFailedNotifications();setPushStatus(result.queued?`已把 ${result.queued} 条失败通知重新加入发送队列。`:'没有需要重试的失败通知。');setNotificationStatus(await loadNotificationStatus());}catch(reason){setPushStatus(reason instanceof Error?reason.message:'通知重试失败');}finally{setBusy(false);}}
  async function testService(){setBusy(true);setServiceStatus('');try{saveApiBase(apiDraft);saveAccessToken(accessTokenDraft);const health=await checkBackend();setBackendOnline(true);const labels:Record<string,string>={database:'数据库',deepseek:'DeepSeek',minimax:'MiniMax 音色',scheduler:'主动陪伴调度令牌',accessProtection:'个人访问保护',push:'推送密钥'};const missing=health.missing.map(item=>labels[item]||item);setServiceStatus(health.ready?`连接正常 · ${health.memoryCount} 条记忆 · 全部服务已就绪`:`连接正常 · ${health.memoryCount} 条记忆 · 还缺：${missing.join('、')}`);}catch(reason){setBackendOnline(false);setServiceStatus(reason instanceof Error?reason.message:'连接失败');}finally{setBusy(false);}}
  function storeService(){try{saveApiBase(apiDraft);saveAccessToken(accessTokenDraft);setServiceStatus('连接信息已保存，正在重新连接…');window.setTimeout(()=>location.reload(),400);}catch(reason){setServiceStatus(reason instanceof Error?reason.message:'地址无效');}}
  function chooseTheme(value:string){localStorage.setItem('mlp_v2_theme',value);setTheme(value);}
  function chooseFont(value:string){localStorage.setItem('mlp_v2_font',value);setFontStyle(value);}
